import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>手机里存的是 HEIC，相机拍的是 JPG，设计师用的是 PNG，网站上跑的又是 WebP。同一张图片，换个地方就可能打不开。</p>\n<p>图片格式转换就是为了解决这种不匹配。它把文件从一种格式改写成另一种，画面本身不变，只是换了个“外壳”，走到哪里都能用。</p>\n<p>这篇指南会讲清楚转换是怎么回事、该选哪种格式，以及怎样每次都得到干净的结果。画质设置、透明背景、批量转换和最常见的坑，都会一一讲到。</p>\n<h2 id=\"what-is-an-image-converter\">什么是图片格式转换工具？</h2>\n<p>图片格式转换工具能把一张图片的文件格式换掉，但画面内容原封不动。给它一张 JPG，它能还你一张 PNG、WebP，或者它支持的任何格式。</p>\n<p>转换改写的是像素的存储方式。JPG 用有损压缩存颜色，PNG 则无损保存。看起来一样，用起来却大不相同。</p>\n<p>大家转格式都是出于实际需要，很少是为了好玩。有的表格只收 JPG，有的网站只认 WebP，有的打印店非 PNG 不可。转换工具就是在“手头有的”和“对方要的”之间搭一座桥。</p>\n<p>CompressMyPic 的转换器完全在浏览器里运行。文件不用上传到服务器，照片在转换过程中始终留在你自己的设备上。</p>\n<h2 id=\"formats-the-converter-handles\">转换器支持哪些格式？</h2>\n<p>输入支持 JPG、PNG、WebP、HEIC、SVG、BMP、GIF 和 AVIF。手机照片、相机原片、截图、标志，以及从现代网站上下载的图片，基本都覆盖了。</p>\n<p>输出可选 JPG、PNG 或 WebP。这三种已经能满足绝大多数真实需求：照片用 JPG，图形和透明图用 PNG，上网用 WebP。</p>\n<p>HEIC 值得单独说一句，因为 iPhone 默认就用它存照片。很多 Windows 程序和上传表单至今仍拒绝 HEIC，所以把 HEIC 转成 JPG 是这里最常见的任务之一。</p>\n<p>AVIF 是名单里最新的格式。它出现在现代网站和部分安卓相册里，但老软件打不开。把 AVIF 转成 JPG 或 PNG，这些文件就处处可用了。</p>\n<h2 id=\"how-browser-conversion-works\">浏览器里的转换是怎么完成的？</h2>\n<p>把文件拖进转换器后，浏览器会用内置的图片支持把它解码成像素。HEIC 例外，浏览器本身解不了，要靠一个在标签页里运行的小型 WebAssembly 解码器。</p>\n<p>这些像素会被画到 HTML5 Canvas 上，也就是浏览器的绘图层。Canvas 再按你选的格式和画质，把像素重新编码输出。</p>\n<p>全程都在本地进行，所以转换速度取决于你的设备，而不是网速。在现代手机或电脑上，一张大照片一两秒就能转完。</p>\n<p>本地处理还有一个好处：隐私。银行账单截图、证件照、家庭照片都不会离开你的设备，这一点比很多人意识到的更重要。</p>\n<h2 id=\"choosing-the-right-output-format\">输出格式该怎么选？</h2>\n<p>JPG 是照片最稳妥的选择。它擅长处理平滑渐变、肤色和复杂场景，而且全世界所有设备和网站都能打开。兼容性最重要时，就选 JPG。</p>\n<p>需要透明背景或边缘锐利时，选 PNG。标志、图标、带文字的截图、纯色图形，用 PNG 效果最好。</p>\n<p>图片要放到网上，WebP 是最好的选择。同等画质下，它比 JPG 更小，还像 PNG 一样支持透明。现在大多数现代浏览器和建站工具都支持它。</p>\n<p>拿不准的时候，先问这张图是干什么用的。交表格的照片要 JPG，网站上的标志要 PNG 或 WebP，博客配图通常用 WebP。</p>\n<h2 id=\"quality-settings-explained\">画质设置是什么意思？</h2>\n<p>画质滑块控制编码器在写入 JPG 或 WebP 时保留多少细节。数值越高，细节保留越多，文件也越大；数值越低，文件越小，画面越柔和。</p>\n<p>大多数照片用 80% 到 85% 就很好。这个区间文件比原图小得多，不放大细看很难发现差别。</p>\n<p>选 PNG 时滑块会消失，这不是故障。PNG 是无损格式，没有画质可选，每个像素都原样保存，文件多大就是多大。</p>\n<p>网站上的 WebP 照片，75% 到 85% 是个不错的范围。打算打印的照片，把画质推到 90% 或更高，因为打印会暴露屏幕上看不出的瑕疵。</p>\n<h2 id=\"transparency-and-matte-fill\">透明背景与底色填充</h2>\n<p>JPG 存不了透明部分，所以 PNG 转 JPG 时，透明区域必须填上颜色。这个颜色就叫底色，你可以在转换前自己选。</p>\n<p>白色是最常用的选择，因为大多数文档和网页都是白底。转到白底上的标志，放在白底页面或 Word 文档里都很自然。</p>\n<p>深色设计用黑色更合适，特定网站也可以填品牌色。转换器支持任意十六进制颜色，能和页面精确匹配。</p>\n<p>转成 PNG 或 WebP 时，透明部分会原样保留。透明区域依然透明，所以这两种格式更适合标志和贴纸。</p>\n<h2 id=\"converting-batches-and-zip-downloads\">批量转换与 ZIP 打包下载</h2>\n<p>不用一张一张转。把一整个文件夹的混合格式文件拖进队列，选一个输出格式，一次全部转完。</p>\n<p>每个文件独立转换，一张坏图不会拖垮整批。损坏的图片只会显示错误标记，其他正常文件照样完成、照样下载。</p>\n<p>两张以上的文件转完后，点“全部下载”会把它们打成一个 ZIP 包。比起一张一张点下载，省事得多。</p>\n<p>输出文件名会保留原名，只换后缀。beach-day.heic 会变成 beach-day.jpg，哪个文件是哪个，一眼就能分清。</p>\n<h2 id=\"heic-photos-from-iphones\">iPhone 的 HEIC 照片怎么办？</h2>\n<p>iPhone 用 HEIC 存照片，是因为它能在大约一半的体积里存下同样的画质。代价是兼容性，苹果体系之外的很多程序根本打不开 HEIC。</p>\n<p>转换器用一个在浏览器标签页里运行的 WebAssembly 解码器读取 HEIC 文件，在本地解码、渲染，再导出标准的 JPG、PNG 或 WebP。</p>\n<p>转出来的 JPG 常常比原来的 HEIC 大，这是正常的。HEIC 是更高效的格式，JPG 并没有变差，只是存得没那么省空间。</p>\n<p>如果你的 iPhone 总是产出 HEIC，而你更想要 JPG，可以直接在手机相机设置里改。改之前，每批转换也只需要几秒钟。</p>\n<h2 id=\"svg-and-vector-files\">SVG 与矢量文件</h2>\n<p>SVG 和其他格式不一样，它用代码描述形状，而不是像素。存成 SVG 的标志可以放大到任意尺寸，永远不会模糊。</p>\n<p>把 SVG 转成 PNG 或 WebP，就是把这些形状固定成像素。得到的是普通位图，任何应用都能打开，适合那些不接受 SVG 的网站和表单。</p>\n<p>SVG 里链接的外部图片转不过去，因为浏览器在转换时无法获取它们。如果图片必须出现在 PNG 里，要先以 data URI 的形式嵌入 SVG。</p>\n<p>SVG 里的网页字体在转换时也可能回落到默认字体。做标志的话，先在设计工具里把文字转成轮廓再转换，字形才能保持精确。</p>\n<h2 id=\"checking-quality-before-saving\">保存前先检查画质</h2>\n<p>每张转好的卡片上都有“对比”按钮，点开能并排查看原图和转换后的图。拖动分割线，可以仔细检查边缘、文字和细节。</p>\n<p>对比视图还会显示转换前后的文件大小。这个数字能直接告诉你，这次转换到底省了多少空间，而这正是给网页图片转格式的目的。</p>\n<p>重点放大最关键的区域。脸部、小字、锐利的斜线最先暴露压缩损伤，而平滑的天空和虚化的背景则很能藏拙。</p>\n<p>如果结果发虚，把画质滑块调高再转一次。原文件还在队列里，不用重新上传就能换个设置再试。</p>\n<h2 id=\"privacy-and-local-processing\">隐私：文件会去哪里？</h2>\n<p>转换在你的设备上完成，文件永远不会上传到服务器。这是浏览器转换器相对云端服务最大的隐私优势。</p>\n<p>把图片画到 Canvas 上还会顺带清除隐藏的元数据。EXIF 相机信息、GPS 位置标签、相机序列号都不会留下来，在网上分享文件时更安全。</p>\n<p>没有账号，没有服务器上的上传队列，照片也不会留下副本。关掉标签页，整个会话就彻底结束了。</p>\n<p>身份证扫描件、医疗文件这类敏感资料，用本地处理是最稳妥的选择。千万不要把证件上传到你不信任的转换器。</p>\n<h2 id=\"common-mistakes-to-avoid\">最容易犯的几个错误</h2>\n<p>最常见的错误，是把有损的 JPG 转成 PNG，还指望画质变好。不会的。PNG 只是把已经受损的像素完美地存下来，文件变大了，画面还和原来一样有瑕疵。</p>\n<p>另一个错误是忽略底色。透明标志转 JPG 时填了黑色，放在白底页面上看起来就像坏了，而改个颜色只要十秒钟。</p>\n<p>还有人忘了，动态 GIF 转出来会变成静态图。Canvas 只画第一帧，动效就丢了。需要保留动画时，请用 GIF 压缩工具。</p>\n<p>最后，不要把同一个文件在有损格式之间来回转。每轮 JPG 编码都会叠加新的损伤，一定要从手头最好的原文件开始转。</p>\n<h2 id=\"converting-for-different-destinations\">不同用途，该转成什么格式？</h2>\n<p>每个用途都有自己偏爱的格式，转换应该跟着用途走，而不是跟着习惯走。网站要 WebP，表格要 JPG，设计工具要 PNG，同一张原图可能需要转出三个版本。</p>\n<p>放网站上，WebP 是明智的目标。它让页面加载更快，还支持透明，标志和照片都适用。用 80% 的画质转成 WebP，上传到网站即可。</p>\n<p>发邮件，JPG 是稳妥的目标。邮件客户端显示 JPG 最可靠，WebP 支持参差不齐，PNG 又常常太大，超了附件限制。85% 画质的 JPG 是务实之选。</p>\n<p>要打印，照片用 90% 以上画质的 JPG，带文字的文档用 PNG。照片印成高画质 JPG 效果很好，带文字的文档印成 PNG，字母在纸上更锐利。</p>\n<p>发社交媒体，先看平台要求。大多数平台上传后都会自己再转码，所以一张高画质 JPG 通常是最简单的输入。PNG 也行，只是文件更大，上传更慢。</p>\n<h2 id=\"file-naming-and-organisation\">转完之后的文件命名与整理</h2>\n<p>转好的文件值得起个清楚的名字。一个月后，一堆 IMG_4821.jpg 根本没法找。保留原名、换掉后缀，再加个用途小标签，比如 hero-web.webp 或 passport-photo.jpg。</p>\n<p>转好的文件和原文件分开存放。建一个 converted 或 web-ready 文件夹，两边互不干扰，既不会误删原稿，也不会发错版本。</p>\n<p>一批转出多种格式时，按格式建子文件夹。WebP 一个文件夹，JPG 一个文件夹，比所有文件挤在一起好找得多，尤其当文件名很像的时候。</p>\n<p>失败或重复的转换结果要及时删掉。半成品堆满的文件夹，每次搜索都慢半拍；整洁的文件夹能让下一次任务更快。</p>\n<p>大批量转换之前，先备份原文件。转好的文件永远变不回完美的原稿，所以原稿值得在另一块硬盘或云端留一份安全副本。</p>\n<p>想试试吗？打开<a href=\"/zh/zhuanhuan-tupian/\">图片格式转换工具</a>，拖一张图片进来就行。想看分步操作，请读<a href=\"/zh/blog/ruhe-zhuanhuan-tupian-geshi/\">如何转换图片格式</a>；想了解画质背后的原理，请看<a href=\"/zh/blog/tupian-geshi-zhuanhuan-huizhi-sunshi-huazhi/\">图片格式转换会损失画质吗</a>。一次要转很多文件的话，<a href=\"/zh/piliang-zhuanhuan-tupian/\">批量图片转换工具</a>可以整批一次搞定。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"转换图片和压缩图片有什么区别？","answer":"转换是改变文件格式，比如把 JPG 换成 PNG；压缩是减小文件体积，通常不换格式。转换有时也能让文件变小，比如 JPG 转 WebP，但它的主要任务是解决兼容问题。压缩则保留格式，只求更小。"},{"question":"转换图片会改变像素尺寸吗？","answer":"不会，默认情况下宽高保持不变。一张 4000×3000 的照片转完还是 4000×3000，变的只是格式和文件大小。如果还需要更小的尺寸，转换后再用图片尺寸调整工具处理。"},{"question":"能不能无损转换图片？","answer":"可以，只要目标格式是无损的。JPG 转 PNG 不会在原有损伤之外再丢细节，在这个工具里，PNG 是无损选项，WebP 使用画质滑块，所以 PNG 转 WebP 的保真程度取决于画质设置。转成 JPG 则总会有一些损失，重要照片记得把画质滑块调高。"},{"question":"为什么转好的文件名字变了？","answer":"转换器会保留原文件名，只换后缀，比如 beach-day.heic 变成 beach-day.jpg。这样文件依然好整理，一眼就能看出哪个是转换后的副本。如果两个文件名撞了，浏览器下载时会自动加数字区分。"},{"question":"在浏览器里转换图片需要安装软件吗？","answer":"不需要。在 Windows、Mac、Linux、ChromeOS、安卓和 iOS 的现代浏览器里都能直接用。不用装应用，也不用注册账号。打开页面，拖入文件，下载结果就行。"},{"question":"转出来的图片比原图差怎么办？","answer":"把画质滑块调高，用原文件再转一次，原文件还留在队列里。也要检查是不是选错了格式，比如细节丰富的照片用了低画质 JPG。如果原图本身画质就低，再怎么设置也变不出本来没有的细节。"}];
